-- Migración pendiente de aplicación. Prisma db migrate controla la transacción.
-- Origen esperado: 1ff57f93f03da3985a78b7eef6739d2c5ce6aa1270f687f755a496a38289dde1
-- Esta migración preserva los datos actuales de gp_matrimonio y gp_proyecto.

-- 1. Catálogo de tipos de ceremonia.
CREATE TABLE "public"."gp_tipo_ceremonia" (
  "id_tipo_ceremonia" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "codigo" character varying(50) NOT NULL,
  "nombre" character varying(100) NOT NULL,
  "descripcion" character varying(500),
  "activo" boolean NOT NULL DEFAULT true,
  CONSTRAINT "gp_tipo_ceremonia_pkey" PRIMARY KEY ("id_tipo_ceremonia"),
  CONSTRAINT "gp_tipo_ceremonia_codigo_key" UNIQUE ("codigo")
);

INSERT INTO "public"."gp_tipo_ceremonia" ("codigo", "nombre", "descripcion", "activo") VALUES
  ('SIMBOLICO', 'Simbólico', NULL, true),
  ('RELIGIOSO', 'Religioso', NULL, true),
  ('CIVIL', 'Civil', NULL, true),
  ('RELIGIOSO_CIVIL', 'Religioso y civil', NULL, true);

-- 2. Sustituir el CHECK/ENUM lógico anterior de gp_matrimonio por la FK.
ALTER TABLE "public"."gp_matrimonio"
  ADD COLUMN "id_tipo_ceremonia" integer;

UPDATE "public"."gp_matrimonio" AS matrimonio
SET "id_tipo_ceremonia" = tipo."id_tipo_ceremonia"
FROM "public"."gp_tipo_ceremonia" AS tipo
WHERE tipo."codigo" = CASE matrimonio."tipo_ceremonia"
  WHEN 'RELIGIOSO_Y_CIVIL' THEN 'RELIGIOSO_CIVIL'
  ELSE matrimonio."tipo_ceremonia"
END;

ALTER TABLE "public"."gp_matrimonio"
  ADD CONSTRAINT "gp_matrimonio_id_tipo_ceremonia_fkey"
  FOREIGN KEY ("id_tipo_ceremonia")
  REFERENCES "public"."gp_tipo_ceremonia" ("id_tipo_ceremonia")
  ON DELETE RESTRICT;

CREATE INDEX "gp_matrimonio_id_tipo_ceremonia_idx_c038373a"
  ON "public"."gp_matrimonio" ("id_tipo_ceremonia");

ALTER TABLE "public"."gp_matrimonio"
  DROP CONSTRAINT IF EXISTS "gp_matrimonio_tipo_ceremonia_check_8c419e2d";

ALTER TABLE "public"."gp_matrimonio"
  DROP COLUMN "tipo_ceremonia";

-- La migración existente representa los ENUM de Prisma como CHECK textuales,
-- por lo que no existe un TYPE nativo gp_tipo_ceremonia que eliminar.

-- 3. Catálogo de fases de proyecto.
CREATE TABLE "public"."gp_fase_proyecto" (
  "id_fase_proyecto" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "codigo" character varying(50) NOT NULL,
  "nombre" character varying(100) NOT NULL,
  "descripcion" character varying(500),
  "orden" integer NOT NULL,
  "activo" boolean NOT NULL DEFAULT true,
  CONSTRAINT "gp_fase_proyecto_pkey" PRIMARY KEY ("id_fase_proyecto"),
  CONSTRAINT "gp_fase_proyecto_codigo_key" UNIQUE ("codigo")
);

INSERT INTO "public"."gp_fase_proyecto" ("codigo", "nombre", "descripcion", "orden", "activo") VALUES
  ('BORRADOR', 'Borrador', NULL, 1, true),
  ('INICIO', 'Inicio', NULL, 2, true),
  ('PLANIFICACION', 'Planificación', NULL, 3, true),
  ('MONITOREO_Y_CONTROL', 'Monitoreo y control', NULL, 4, true),
  ('EJECUCION', 'Ejecución', NULL, 5, true),
  ('CIERRE', 'Cierre', NULL, 6, true);

-- Se conserva temporalmente el valor textual anterior bajo un nombre auxiliar.
ALTER TABLE "public"."gp_proyecto"
  RENAME COLUMN "estado" TO "estado_legacy";

ALTER TABLE "public"."gp_proyecto"
  ADD COLUMN "id_fase_proyecto" integer,
  ADD COLUMN "estado" boolean NOT NULL DEFAULT true;

UPDATE "public"."gp_proyecto" AS proyecto
SET
  "id_fase_proyecto" = fase."id_fase_proyecto",
  "estado" = true
FROM "public"."gp_fase_proyecto" AS fase
WHERE fase."codigo" = proyecto."estado_legacy";

ALTER TABLE "public"."gp_proyecto"
  ADD CONSTRAINT "gp_proyecto_id_fase_proyecto_fkey"
  FOREIGN KEY ("id_fase_proyecto")
  REFERENCES "public"."gp_fase_proyecto" ("id_fase_proyecto")
  ON DELETE RESTRICT;

CREATE INDEX "gp_proyecto_id_fase_proyecto_idx_0ca9d564"
  ON "public"."gp_proyecto" ("id_fase_proyecto");

ALTER TABLE "public"."gp_proyecto"
  DROP CONSTRAINT IF EXISTS "gp_proyecto_estado_check_8f4f8f4a";

ALTER TABLE "public"."gp_proyecto"
  DROP COLUMN "estado_legacy";

-- Igual que tipo_ceremonia, estado se almacenaba como texto con CHECK; no hay
-- TYPE enum nativo pendiente de eliminar en la base generada por las migraciones.

-- 4. Plantillas. No se insertan registros funcionales en estas tablas.
CREATE TABLE "public"."gp_plantilla_hito" (
  "id_plantilla_hito" SERIAL NOT NULL,
  "codigo" character varying(50) NOT NULL,
  "nombre" character varying(200) NOT NULL,
  "criterio_aceptacion" character varying(1000) NOT NULL,
  "tipo_temporal" text NOT NULL,
  "dias_antes_base" integer,
  "dias_antes_minimo" integer,
  "orden" integer NOT NULL,
  "activo" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL,
  CONSTRAINT "gp_plantilla_hito_pkey" PRIMARY KEY ("id_plantilla_hito"),
  CONSTRAINT "gp_plantilla_hito_codigo_key" UNIQUE ("codigo"),
  CONSTRAINT "gp_plantilla_hito_tipo_temporal_check_77c07874"
    CHECK ("tipo_temporal" IN ('INICIO', 'ESCALABLE', 'FIJO_EVENTO', 'DIA_EVENTO', 'POST_EVENTO'))
);

CREATE TABLE "public"."gp_plantilla_actividad" (
  "id_plantilla_actividad" SERIAL NOT NULL,
  "id_plantilla_hito" integer,
  "id_fase_proyecto" integer NOT NULL,
  "codigo" character varying(50) NOT NULL,
  "nombre" character varying(200) NOT NULL,
  "lista_verificacion" json,
  "responsable_sugerido" character varying(150),
  "entregable" character varying(500),
  "tipo_temporal" text NOT NULL,
  "dias_antes_base" integer,
  "dias_antes_minimo" integer,
  "duracion_estimada_dias" integer,
  "prioridad" text,
  "orden" integer NOT NULL,
  "activo" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL,
  CONSTRAINT "gp_plantilla_actividad_pkey" PRIMARY KEY ("id_plantilla_actividad"),
  CONSTRAINT "gp_plantilla_actividad_codigo_key" UNIQUE ("codigo"),
  CONSTRAINT "gp_plantilla_actividad_tipo_temporal_check_77c07874"
    CHECK ("tipo_temporal" IN ('INICIO', 'ESCALABLE', 'FIJO_EVENTO', 'DIA_EVENTO', 'POST_EVENTO')),
  CONSTRAINT "gp_plantilla_actividad_prioridad_check_a1f6ee2f"
    CHECK ("prioridad" IN ('BAJA', 'MEDIA', 'ALTA', 'CRITICA')),
  CONSTRAINT "gp_plantilla_actividad_id_plantilla_hito_fkey"
    FOREIGN KEY ("id_plantilla_hito")
    REFERENCES "public"."gp_plantilla_hito" ("id_plantilla_hito") ON DELETE RESTRICT,
  CONSTRAINT "gp_plantilla_actividad_id_fase_proyecto_fkey"
    FOREIGN KEY ("id_fase_proyecto")
    REFERENCES "public"."gp_fase_proyecto" ("id_fase_proyecto") ON DELETE RESTRICT
);

CREATE INDEX "gp_plantilla_actividad_id_plantilla_hito_idx_99ae877f"
  ON "public"."gp_plantilla_actividad" ("id_plantilla_hito");
CREATE INDEX "gp_plantilla_actividad_id_fase_proyecto_idx_0ca9d564"
  ON "public"."gp_plantilla_actividad" ("id_fase_proyecto");

CREATE TABLE "public"."gp_plantilla_actividad_tipo_ceremonia" (
